#!/usr/bin/env bash
set -euo pipefail
ROOT=$(cd -- "$(dirname -- "$0")/.." && pwd)
SOURCE="$ROOT/vendor/hapi-source"
BUN="${BUN_BIN:-$HOME/.bun/bin/bun}"
# Applied in order on v0.30.7; each patch is generated on top of the previous one.
PATCHES=(hapi-mobile-models.patch hapi-sidebar-chats.patch hapi-chat-folders.patch hapi-chat-controls.patch hapi-session-goals.patch hapi-manager-pin.patch hapi-no-manager-bar.patch hapi-managed-indicator.patch hapi-context-accuracy.patch hapi-slash-command-arguments.patch hapi-usage-shortcut.patch hapi-codex-context-toggle.patch hapi-codex-context-per-chat.patch hapi-chat-statistics.patch hapi-claude-immediate-send.patch hapi-native-input-priorities.patch hapi-background-progress.patch hapi-queued-send-now.patch hapi-side-chats-newline.patch hapi-subagent-viewer.patch hapi-background-task-viewer.patch hapi-native-task-completion.patch hapi-activity-cleanup.patch hapi-claude-send-when-ready.patch hapi-temporary-sessions.patch hapi-idle-background-status.patch hapi-new-session-defaults.patch hapi-device-enter.patch hapi-temporary-claude-identity.patch hapi-composer-undo.patch hapi-queue-edit-status.patch hapi-response-streaming.patch hapi-ready-edit-visibility.patch hapi-inactive-codex-models.patch hapi-folders-provider-handoff.patch hapi-manual-pause-folder-drag.patch hapi-in-chat-notes.patch hapi-session-manager.patch hapi-session-manager-filters.patch hapi-session-manager-compact.patch hapi-session-controls-resume.patch hapi-compact-tool-reasoning.patch hapi-reasoning-spacing.patch hapi-session-manager-width.patch hapi-touch-folder-gestures.patch hapi-managed-session-inclusion.patch hapi-current-session-roster.patch hapi-managed-observer-race.patch hapi-consistent-managed-label.patch hapi-session-manager-runtime-retention.patch hapi-floating-session-manager.patch hapi-session-manager-pins.patch hapi-session-manager-bubble.patch hapi-dictation-button.patch hapi-stopped-background-tasks.patch hapi-response-fork-prompt-edit.patch hapi-durable-session-manager.patch hapi-empty-folders.patch hapi-session-manager-collapse-pins.patch hapi-session-manager-manual-add.patch hapi-session-manager-bubble-position.patch hapi-background-output-status.patch hapi-opus-review-controls.patch hapi-opus-review-status-retention.patch hapi-node-graph.patch hapi-desktop-popouts-sidebar.patch hapi-graph-controls-drop.patch hapi-node-inputs-undo-stop.patch hapi-background-receipt-proof.patch hapi-node-annotations.patch hapi-node-junctions.patch hapi-codex-fast-toggle.patch hapi-chat-navigation-add-menu.patch hapi-overseer-tree-control.patch hapi-desktop-midnight-theme.patch hapi-idle-node-connections.patch hapi-lightning-ui.patch hapi-side-chat-tools.patch hapi-mobile-density-sidebar-width.patch hapi-input-end-rewire.patch hapi-node-context-menu.patch hapi-header-chat-pin.patch hapi-compact-section-cleanup.patch hapi-frame-grid-failure-status.patch hapi-peer-message-provenance.patch hapi-sidebar-card-layout.patch hapi-verified-local-background.patch hapi-input-delivery-receipts.patch hapi-helper-process-lifecycle.patch hapi-mobile-popouts-stay-open.patch hapi-session-manager-compact-rows.patch hapi-session-manager-header-filters.patch hapi-nodes-header-add-search.patch hapi-composer-preview-surface.patch hapi-centered-popout-expansion.patch hapi-floating-header-drag.patch hapi-node-grid-cell-size.patch hapi-header-control-drag.patch hapi-session-footer-top-anchor.patch hapi-popout-top-ready-toast.patch hapi-ui-disconnect-redo.patch hapi-chat-header-selector-layout.patch hapi-node-box-selection.patch hapi-full-width-chat-chrome.patch hapi-header-icon-polish.patch hapi-full-height-selector-panel.patch hapi-flat-chat-selector-header.patch hapi-goal-activity-header-popovers.patch hapi-single-line-session-manager.patch hapi-node-grid-icon.patch hapi-codex-tool-catalog-refresh.patch hapi-session-manager-aligned-abort.patch hapi-multi-node-drag.patch hapi-chat-popout-ownership.patch hapi-overseer-clean-conversation.patch hapi-runner-session-isolation.patch hapi-graph-labels-nesting-view.patch hapi-frame-anchored-actions.patch hapi-node-workspace-preview.patch hapi-node-spawn-placement.patch hapi-mobile-node-box-selection.patch hapi-mobile-node-double-tap.patch hapi-node-rename-action.patch hapi-junction-context-chains-selection.patch hapi-compact-graph-curves-frames.patch hapi-frame-insets-selection.patch hapi-junction-label-frame-bounds.patch hapi-junction-aligned-frame-top.patch hapi-text-box-graph-selection.patch hapi-folder-delete-manager-pin.patch hapi-folder-tree-drag.patch hapi-folder-graph-drop.patch hapi-remove-lone-label.patch hapi-session-evidence-oversight.patch hapi-node-graph-scaling.patch hapi-auto-node-ports.patch hapi-junction-label-spacing.patch hapi-session-manager-left-columns.patch hapi-shared-terminal-failure-status.patch hapi-frame-interior-pointer-pass.patch hapi-junction-move-mobile-object-tap.patch hapi-idle-input-receipts-visible-edit.patch hapi-saved-goal-status-scope.patch hapi-tail-scroll-layout-guard.patch hapi-prepend-visible-anchor.patch hapi-inactive-effort.patch hapi-folder-transport-recovery.patch)
if [[ ! -d "$SOURCE/.git" ]]; then
    git clone --branch v0.30.7 --depth 1 https://github.com/tiann/hapi.git "$SOURCE"
fi
cd "$SOURCE"
# Find the newest patch already applied (later patches touch the same files,
# so earlier ones only reverse-apply while later ones are absent).
applied=0
for ((i=${#PATCHES[@]}; i>0; i--)); do
    if git apply --reverse --check "$ROOT/patches/${PATCHES[i-1]}" 2>/dev/null; then
        applied=$i
        break
    fi
done
for ((i=applied; i<${#PATCHES[@]}; i++)); do
    git apply --check "$ROOT/patches/${PATCHES[i]}"
    git apply "$ROOT/patches/${PATCHES[i]}"
done
"$BUN" install --frozen-lockfile
# Hub-side ChatGPT folder API (hub restart needed for hub changes; web swaps live).
(cd hub && "$BUN" run typecheck && "$BUN" test ../shared/src/nodeGraph.offline.test.ts ../shared/src/nodePlacement.test.ts ../shared/src/backgroundTaskReceipt.test.ts src/managerControl.test.ts src/web/routes/sessions.test.ts src/sync/serviceTier.test.ts src/sync/manualPause.test.ts src/sync/sessionManager.test.ts src/sync/nodeGraph.test.ts src/store/messages.test.ts src/sync/turnFailure.test.ts src/sync/turnFailure.backfill.test.ts src/sync/nodeTree.test.ts src/sync/messageService.test.ts src/coordinationOrigins.test.ts src/web/routes/messages.test.ts ../shared/src/apiTypes.test.ts src/web/routes/codexFolders.test.ts src/web/routes/providerHandoff.test.ts src/sessionGoals.test.ts src/web/routes/managedSessions.test.ts src/web/routes/codexContext.test.ts src/chatStatistics.test.ts src/web/routes/chatStatistics.test.ts src/sync/usageService.test.ts src/sync/backgroundTasks.test.ts src/sync/claudeTaskCompletion.test.ts src/sync/sessionCache.backgroundTasks.test.ts src/sync/localProcesses.test.ts src/sync/sessionCache.localProcesses.test.ts src/store/backgroundStatus.test.ts src/sync/sessionCache.applySessionPatch.test.ts ../shared/src/schemas.sessionPatch.test.ts ../shared/src/sessionSummary.test.ts src/sync/steerQueuedMessage.test.ts src/sync/temporarySession.test.ts src/socket/handlers/cli/sessionHandlers.test.ts src/web/routes/machines.test.ts src/sideChats.test.ts src/web/routes/sideChats.test.ts src/backgroundTaskOutput.test.ts src/web/routes/backgroundTasks.test.ts)
# User requested selecting Desktop Midnight once per browser; later choices persist.
export VITE_DESKTOP_THEME_SELECTION="${VITE_DESKTOP_THEME_SELECTION-desktop-midnight-v1}"
# Deployment identity stays in ignored local state, never in public source.
if [[ -z "${VITE_MANAGER_SESSION_ID:-}" && -f "$ROOT/state/local-config.json" ]]; then
    VITE_MANAGER_SESSION_ID=$(python3 -c 'import json,sys; print(json.load(open(sys.argv[1])).get("manager_session_id", ""))' "$ROOT/state/local-config.json")
fi
export VITE_MANAGER_SESSION_ID="${VITE_MANAGER_SESSION_ID:?Set VITE_MANAGER_SESSION_ID or state/local-config.json manager_session_id}"
cd web
"$BUN" run typecheck
"$BUN" run test --maxWorkers=2 src/hooks/useColorTheme.test.ts src/hooks/useTheme.test.ts src/hooks/themeBootstrap.test.ts src/hooks/useThemeColors.test.ts src/hooks/useChatSurfaceColors.test.ts src/routes/settings/index.test.tsx src/components/AssistantChat/RichComposerInput.test.tsx src/components/NewSession/ActionButtons.test.tsx src/components/NewSession/ModelSelector.test.tsx src/components/NewSession/EffortField.test.tsx src/components/NewSession/index.test.tsx src/lib/resolvedChoices.test.ts src/lib/claudeCatalogChoices.test.ts src/components/AssistantChat/codexFastMode.test.ts src/components/AssistantChat/modelOptions.test.ts src/components/AssistantChat/HappyComposer.modelEffortButtons.test.tsx src/components/QuickApproval.test.tsx \
    src/components/SessionList src/hooks/useLongPress.test.tsx src/components/SessionRowSummary.test.tsx src/components/SessionAttentionIndicator.test.tsx src/components/AssistantChat/QueuedMessagesBar.test.tsx src/components/SideChatButton.test.tsx src/components/SubagentsPanel.test.tsx src/components/SessionActivityPanel.test.tsx src/components/AssistantChat/StatusBar.popover.test.tsx src/components/AssistantChat/ComposerButtons.test.tsx src/components/AssistantChat/SortableComposerAttachments.test.tsx src/components/AssistantChat/SortableComposerAttachments.preview.test.tsx src/components/AssistantChat/AttachmentItem.test.tsx src/components/ImagePreview.test.tsx src/hooks/useDictation.test.ts src/hooks/useRealtimeDictation.test.ts src/hooks/realtimeTranscription.test.ts src/components/AssistantChat/NativeReadyMessages.test.tsx src/lib/queuedDeliveryStatus.test.ts src/chat/normalize/normalize.test.ts src/lib/message-window.test.ts src/lib/messageDelivery.test.ts src/components/ToolCard src/components/assistant-ui/reasoning.test.tsx src/hooks/useReasoningCollapse.test.ts src/components/BackgroundTasksPanel.test.tsx src/lib/backgroundProcesses.test.ts src/chat/backgroundTaskViews.test.ts src/chat/sessionStatus.test.ts src/components/ToolCard/trace.test.tsx src/hooks/useComposerEnterBehavior.test.ts src/chat/coordination.test.ts src/components/OverseerActivity.test.tsx src/components/AssistantChat/messages/UserMessage.test.tsx src/components/AssistantChat/messages/supervisorBatch.test.ts src/components/GoalBanner.test.tsx src/components/ChatHeaderPopover.test.tsx src/components/RunningBar.test.tsx src/chat/contextUsage.test.ts src/utils/findActiveWord.test.ts src/hooks/useActiveSuggestions.test.tsx src/components/AssistantChat/CodexContextToggle.test.tsx src/components/AssistantChat/ChatStatisticsButton.test.tsx src/hooks/mutations/useSendMessage.test.tsx src/components/SessionChat.test.ts src/components/SessionHeader.test.tsx src/components/ProviderHandoff.test.tsx src/api/client.test.ts src/components/AssistantChat/HappyComposer.sendError.test.tsx src/components/SessionManagerButton.test.tsx src/components/SessionManagerRace.test.tsx src/components/SessionManagerWindow.test.tsx src/lib/popout.test.ts src/hooks/useNodeChatPin.test.tsx src/components/PopoutNavigation.test.tsx src/components/SessionActionMenu.test.tsx src/hooks/useMobileSidebar.test.tsx src/hooks/useSidebarResize.test.tsx src/lib/sessionManager.test.ts src/lib/nodeGraphLayout.test.ts src/lib/sessionDrag.test.ts src/lib/chatFolderTree.test.ts src/lib/sessionEvidence.test.ts src/components/SessionOversightBadge.test.tsx src/lib/folderGraphDrop.test.ts src/components/ChatFolderDragButton.test.tsx src/lib/nodeGraphUndo.test.ts src/lib/nodeGraphJunctions.test.ts src/lib/nodePorts.test.ts src/components/NodeGraphView.test.tsx src/components/NodeGraphHost.test.tsx src/routes/popout.test.tsx src/components/NodeGraphFailureStatus.test.ts src/components/SessionFailureBanner.test.tsx src/lib/sessionFailure.test.ts src/lib/nodeFrames.test.ts src/hooks/useNodeGrid.test.ts src/components/UtilityPanelHost.test.tsx src/components/AssistantChat/HappyThread.test.tsx src/api/nodeGraphClient.test.ts src/hooks/useManagedSessions.test.tsx src/hooks/useSessionManager.test.tsx src/lib/sessionManagerActivity.test.ts src/hooks/useSSE.test.ts src/components/ManualPauseBanner.test.tsx src/components/MarkdownRenderer.test.tsx src/components/assistant-ui/markdown-text.test.ts src/components/assistant-ui/markdown-text-codeblock.test.tsx src/lib/remark-latex-bracket-math.test.ts src/components/AssistantChat/messages/NotifySummaryText.test.tsx src/lib/history-prompt.test.ts src/lib/assistant-runtime.test.ts src/components/AssistantChat/messages/MessageActions.test.tsx
# Build beside the served bundle, then swap: the hub serves web/dist from disk.
rm -rf dist-next
./node_modules/.bin/vite build --outDir dist-next --emptyOutDir
# Refuse to publish a bundle that silently lost the persistent manager pin.
if ! rg --fixed-strings --quiet "$VITE_MANAGER_SESSION_ID" dist-next/assets/index-*.js; then
    echo "Manager identity missing from web bundle; refusing publication" >&2
    exit 1
fi
cp dist-next/index.html dist-next/404.html
rm -rf dist-prev
if [[ -d dist ]]; then mv dist dist-prev; fi
mv dist-next dist
